import matplotlib.pyplot as plt
import numpy as np
import pickle
with open('logs/speculative_metrics_1.pkl', 'rb') as f:
    speculative_metrics_cache = pickle.load(f)
print(speculative_metrics_cache)
acceptance_rate = speculative_metrics_cache
# Create figure and axis
plt.figure(figsize=(12, 6))

# Create histogram
plt.hist(acceptance_rate, bins=20, edgecolor='black')

# Customize the plot
plt.title('Distribution of Acceptance Rates')
plt.xlabel('Acceptance Rate')
plt.ylabel('Frequency')

# Add grid
plt.grid(True, alpha=0.3)

# Adjust layout
plt.tight_layout()

# Save the plot
plt.savefig('./figs/acceptance_rate_histogram_ngram_70B1.png')
plt.close()
